487	static void helm_show(lv_obj_t * obj, bool on)
488	{
489	    if (obj == NULL) {
490	        return;
491	    }
492	
493	    if (on) {
494	        if (lv_obj_has_flag(obj, LV_OBJ_FLAG_HIDDEN)) {
495	            lv_obj_clear_flag(obj, LV_OBJ_FLAG_HIDDEN);
496	            lv_obj_move_foreground(obj);
497	        }
498	    } else if (!lv_obj_has_flag(obj, LV_OBJ_FLAG_HIDDEN)) {
499	        lv_obj_add_flag(obj, LV_OBJ_FLAG_HIDDEN);
500	    }
501	}
502	
503	static bool helm_obj_shown(const lv_obj_t * obj)
504	{
505	    return obj != NULL && !lv_obj_has_flag((lv_obj_t *)obj, LV_OBJ_FLAG_HIDDEN);
506	}
