512	static void helm_raise_if_shown(lv_obj_t * obj)
513	{
514	    lv_obj_t * parent;
515	
516	    if (!helm_obj_shown(obj)) {
517	        return;
518	    }
519	
520	    parent = lv_obj_get_parent(obj);
521	    if (parent == NULL) {
522	        return;
523	    }
524	
525	    if (lv_obj_get_index(obj)
526	        != (int32_t)lv_obj_get_child_count(parent) - 1) {
527	        lv_obj_move_foreground(obj);
528	    }
529	}
