559	/**
560	 * @brief 导航横幅显隐（幂等）。
561	 * @param animate 只在导航开始/结束时为 true；切页一律 false（snap，不播退场）。
562	 * @details `helm_apply_view()` 每次切页都会调用：已显示的横幅必须原样返回，
563	 *          不能每拍重播入场。退场之后仍复用同一棵对象树，只改 HIDDEN。
564	 */
565	static void helm_nav_ban_show(bool on, bool animate)
566	{
567	    if (s_sh.nav_ban == NULL) {
568	        return;
569	    }
570	
571	    if (on) {
572	        if (!lv_obj_has_flag(s_sh.nav_ban, LV_OBJ_FLAG_HIDDEN)) {
573	            /* 已显示：退场中要取消并复位；**入场中不能打断** —— 周期块每
574	             * 500 ms 会再进来一次，这里若一律归零，160 ms 的入场会被截短。 */
575	            if (s_nav_ban_hiding || !animate) {
576	                s_nav_ban_hiding = false;
577	                helm_anim_stop(s_sh.nav_ban, helm_nav_ban_y_exec);
578	                lv_obj_set_style_translate_y(s_sh.nav_ban, 0, 0);
579	            }
580	            return;
581	        }
582	
583	        s_nav_ban_hiding = false;
584	        helm_anim_stop(s_sh.nav_ban, helm_nav_ban_y_exec);
585	        lv_obj_clear_flag(s_sh.nav_ban, LV_OBJ_FLAG_HIDDEN);
586	        /* 与旧 `helm_show()` 同语义：只有"从藏到显"这一下才抬层级。 */
587	        lv_obj_move_foreground(s_sh.nav_ban);
588	        if (animate && !helm_anim_is_suspended()) {
589	            lv_obj_set_style_translate_y(s_sh.nav_ban, -8, 0);
590	            helm_anim_run(s_sh.nav_ban, helm_nav_ban_y_exec, -8, 0, 160,
591	                          lv_anim_path_ease_out, helm_nav_ban_y_done);
592	        } else {
593	            lv_obj_set_style_translate_y(s_sh.nav_ban, 0, 0);
594	        }
595	        return;
596	    }
597	
598	    if (lv_obj_has_flag(s_sh.nav_ban, LV_OBJ_FLAG_HIDDEN)) {
599	        return;
600	    }
601	
602	    if (animate && !helm_anim_is_suspended()) {
603	        int32_t cur;
604	
605	        if (s_nav_ban_hiding) {
606	            return;  /* 已经在下滑：不要从 0 再启动一次，否则屏上会跳一下 */
607	        }
608	        s_nav_ban_hiding = true;
609	        /* 从当前偏移接着滑（入场还没走完就结束导航时不要先跳回 0）。 */
610	        cur = lv_obj_get_style_translate_y(s_sh.nav_ban, 0);
611	        helm_anim_run(s_sh.nav_ban, helm_nav_ban_y_exec, cur, -8, 140,
612	                      lv_anim_path_ease_in, helm_nav_ban_y_done);
613	    } else {
614	        /* 切页/挂起：立即收起，不留半截动画。 */
615	        helm_anim_stop(s_sh.nav_ban, helm_nav_ban_y_exec);
616	        s_nav_ban_hiding = false;
617	        lv_obj_add_flag(s_sh.nav_ban, LV_OBJ_FLAG_HIDDEN);
618	        lv_obj_set_style_translate_y(s_sh.nav_ban, 0, 0);
619	    }
620	}
