3693	static void helm_finish_ride(bool keep)
3694	{
3695	    bicycle_runtime_save_last_pos();
3696	    if (keep) {
3697	        const bicycle_runtime_t * rt = bicycle_runtime_get();
3698	        char path[128];
3699	        const char * base;
3700	
3701	        path[0] = '\0';
3702	
3703	        {
3704	            int gpx_ret = bicycle_ride_gpx_commit(path, sizeof(path));
3705	
3706	            if (gpx_ret == 0 && path[0] != '\0') {
3707	                base = strrchr(path, '/');
3708	                base = (base != NULL && base[1] != '\0') ? base + 1 : path;
3709	                if (rt != NULL) {
3710	                    s_sh.last_km = (float)(rt->session_distance_m / 1000.0);
3711	                    helm_ride_stat_remember(path,
3712	                        rt->session_distance_m / 1000.0,
3713	                        (uint32_t)(rt->session_elapsed_ms / 1000ull));
3714	                    myvendor_devctl_last_ride_m_set(
3715	                        (int32_t)(rt->session_distance_m + 0.5));
3716	                }
3717	
3718	                lv_pm_notify_show("已保存", base, 2000);
3719	            } else if (gpx_ret == -ENODATA) {
3720	                lv_pm_notify_show("骑行", "无轨迹，未保存", 2000);
3721	            } else {
3722	                lv_pm_notify_show("骑行", "GPX 保存失败", 2000);
3723	            }
3724	        }
3725	
3726	        myvendor_sound_save();
3727	    } else {
3728	        (void)bicycle_ride_gpx_discard();
3729	    }
3730	
3731	    helm_save_hide();
3732	    helm_leave_ride();
3733	}
