1060	static void dial_tick_layout(int cx, int cy, int d)
1061	{
1062	    for (int i = 0; i < 24; i++) {
1063	        const int deg = i * 15;
1064	        const bool major = (i % 6 == 0);
1065	        const double a = (double)deg * DEG2RAD;
1066	        const double r1 = (major ? 66.0 : 69.0) * (double)d / 160.0;
1067	        const double r2 = 74.0 * (double)d / 160.0;
1068	
1069	        UD.tick_pts[i][0].x = cx + (int)lround(sin(a) * r1);
1070	        UD.tick_pts[i][0].y = cy - (int)lround(cos(a) * r1);
1071	        UD.tick_pts[i][1].x = cx + (int)lround(sin(a) * r2);
1072	        UD.tick_pts[i][1].y = cy - (int)lround(cos(a) * r2);
1073	        if (UD.tick[i] != NULL) {
1074	            lv_line_set_points(UD.tick[i], UD.tick_pts[i], 2);
1075	        }
1076	    }
1077	}
1078	
1079	static void dial_pointer_layout(int angle)
1080	{
1081	    const double a = (double)angle * DEG2RAD;
1082	    const double sx = sin(a);
1083	    const double sy = -cos(a);
1084	    const double px = cos(a);
1085	    const double py = sin(a);
1086	    /* 舵柄按盘径缩放（转场时一起缩），基准盘径 140：
1087	     * 内端 r=52 避开盘心文字，外端 r=72（环外 2px）给模式名留 >9px 安全距。 */
1088	    const double sc = (double)UD.d / 140.0;
1089	    const double r0 = 52.0 * sc;
1090	    const double r1 = 72.0 * sc;
1091	    const int x0 = UD.cx + (int)lround(sx * r0);
1092	    const int y0 = UD.cy + (int)lround(sy * r0);
1093	    const int x1 = UD.cx + (int)lround(sx * r1);
1094	    const int y1 = UD.cy + (int)lround(sy * r1);
1095	    const int cw = (int)lround(8.0 * sc);
1096	
1097	    UD.ptr_pts[0].x = x0;
1098	    UD.ptr_pts[0].y = y0;
1099	    UD.ptr_pts[1].x = x1;
1100	    UD.ptr_pts[1].y = y1;
1101	    UD.cross_pts[0].x = x1 - (int)lround(px * cw);
1102	    UD.cross_pts[0].y = y1 - (int)lround(py * cw);
1103	    UD.cross_pts[1].x = x1 + (int)lround(px * cw);
1104	    UD.cross_pts[1].y = y1 + (int)lround(py * cw);
1105	    if (UD.ptr != NULL) {
1106	        lv_line_set_points(UD.ptr, UD.ptr_pts, 2);
1107	    }
1108	    if (UD.cross != NULL) {
1109	        lv_line_set_points(UD.cross, UD.cross_pts, 2);
1110	    }
1111	}
