1261	/* 盘下常驻：本周里程/次数 + 7 根迷你柱。柱与记录页同一套画法：
1262	 * 8px 宽、12px 间距、0 值 P_TRACK、其余 C_DEEP[M_RECORD]、圆角 1。 */
1263	static void dial_week_strip(void)
1264	{
1265	    char buf[48];
1266	    double mx = 1.0;
1267	
1268	    for (int i = 0; i < 7; i++) {
1269	        if (s_week[i] > mx) mx = s_week[i];
1270	    }
1271	    snprintf(buf, sizeof(buf), "本周 %.1f %s · %d 次",
1272	             conv_dist(week_total()), unit_dist(), week_rides());
1273	    (void)LW(s_scr, buf, PX_SMALL, P_INK, 0, 248, 240, LV_TEXT_ALIGN_CENTER);
1274	    for (int i = 0; i < 7; i++) {
1275	        int h = (int)((s_week[i] * 18.0) / mx);
1276	
1277	        if (h < 2) h = 2;
1278	        (void)B(s_scr, 80 + i * 12, 284 - h, 8, h,
1279	                s_week[i] == 0 ? P_TRACK : C_DEEP[M_RECORD], LV_OPA_COVER, 1);
