1283	static void dial_build(void)
1284	{
1285	    memset(&UD, 0, sizeof(UD));
1286	    s_screen = SCR_DIAL;
1287	    d_bg(s_scr, P_PAPER);
1288	    /* 环形页与骑行三页共用同一条状态栏（y=0..24）。 */
1289	    statusbar_build();
1290	
1291	    UD.cx = DIAL_CX;
1292	    UD.cy = DIAL_CY;
1293	    UD.d = DIAL_D;
1294	    s_angle = s_mode * 90;
1295	    UD.angle = s_angle;
1296	
1297	    /* 整圈未选轨道 + 选中扇区（浅 20% + 深色 2px 外沿）。 */
1298	    UD.ring = RING(s_scr, UD.cx, UD.cy, UD.d, 2, P_TRACK);
1299	    dial_sector(s_mode, LV_OPA_COVER, &UD.fill, &UD.trk);
1300	
1301	    /* 24 刻度：每 15°，整点 3px。 */
1302	    for (int i = 0; i < 24; i++) {
1303	        const bool major = (i % 6 == 0);
1304	
1305	        UD.tick[i] = LINE(s_scr, UD.tick_pts[i], 2, major ? 3 : 1,
1306	                          major ? P_INK : P_TICK);
1307	    }
1308	    /* 舵柄：中心到外圈 + 8px 横杆。 */
1309	    UD.ptr = LINE(s_scr, UD.ptr_pts, 2, 3, P_INK);
1310	    UD.cross = LINE(s_scr, UD.cross_pts, 2, 3, P_INK);
1311	
1312	    /* 盘心：图标底 + 模式名 / 描述 / 主值 / 副行，装进一个容器方便整体淡入。 */
1313	    UD.hub = lv_obj_create(s_scr);
1314	    lv_obj_remove_style_all(UD.hub);
1315	    lv_obj_set_pos(UD.hub, 40, 84);
1316	    lv_obj_set_size(UD.hub, 160, 108);
1317	    lv_obj_remove_flag(UD.hub, LV_OBJ_FLAG_SCROLLABLE);
1318	    lv_obj_remove_flag(UD.hub, LV_OBJ_FLAG_CLICKABLE);
1319	
1320	    {
1321	        /* 标题：文字 160 宽居中；20px 图标由 dial_title_layout() 摆到左侧。 */
1322	        UD.chip = NULL;
1323	        UD.icon = hfi_create_px(UD.hub, mode_icon(s_mode), 20, 0, 0,
1324	                                C_DEEP[s_mode]);
1325	        UD.name = LW(UD.hub, "", PX_TITLE, P_INK, 0, 0, 160,
1326	                     LV_TEXT_ALIGN_CENTER);
1327	    }
1328	    UD.desc = LW(UD.hub, "", PX_SMALL, P_MUTE, 0, 38, 160,
1329	                 LV_TEXT_ALIGN_CENTER);
1330	    {
1331	        /* 22px 数字 + 11px 单位：共用基线（hub_value_layout）。 */
1332	        UD.value = L(UD.hub, "", PX_VALUE, P_INK, 0, 55);
1333	        UD.unit = L(UD.hub, "", PX_MICRO, P_MUTE, 0, 66);
1334	    }
1335	    HAIR(UD.hub, 64, 87, 32);
1336	    UD.sub = LW(UD.hub, "", PX_MICRO, P_MUTE, 0, 92, 160,
1337	                LV_TEXT_ALIGN_CENTER);
1338	
1339	    /* 模式名：4 个方位，选中 15px。半径 99：文字墨迹内缘 r≈83，
1340	     * 与舵柄最外墨迹 r≈73 留 10px 安全距（脚本断言见证据）。 */
1341	    {
1342	        static const int lx[4] = { 0, 1, 0, -1 };
1343	        static const int ly[4] = { -1, 0, 1, 0 };
1344	
1345	        for (int i = 0; i < 4; i++) {
1346	            UD.labels[i] = LW(s_scr, mode_name(i), PX_SMALL, P_MUTE,
1347	                              DIAL_CX + lx[i] * 99 - 20,
1348	                              DIAL_CY + ly[i] * 99 - 8,
1349	                              40, LV_TEXT_ALIGN_CENTER);
1350	        }
1351	    }
1352	
1353	    /* 状态（记录/暂停/导航）由顶部状态栏徽章表达，盘面不再重复文字。 */
1354	
1355	    dial_week_strip();
1356	    dial_content(s_mode);
1357	    dial_geometry(DIAL_CX, DIAL_CY, DIAL_D, 255);
1358	}
