1371	{
1372	    (void)var;
1373	    s_angle = s_rot_a0 + (s_rot_a1 - s_rot_a0) * (int)p / 1000;
1374	    UD.angle = s_angle;
1375	    dial_pointer_layout(s_angle);
1376	    s_rot_oa_cur = s_rot_oa0 * (1000 - (int)p) / 1000;
1377	    s_rot_ob_cur = s_rot_ob0 + (255 - s_rot_ob0) * (int)p / 1000;
1378	    SET_ARC_OPA(UD.fill, s_rot_oa_cur);
1379	    SET_ARC_OPA(UD.trk, s_rot_oa_cur);
1380	    SET_ARC_OPA(UD.fill2, s_rot_ob_cur);
1381	    SET_ARC_OPA(UD.trk2, s_rot_ob_cur);
1382	    if (!s_rot_swapped && p >= 500) {
1383	        s_rot_swapped = true;
1384	        dial_content(s_rot_to_mode);
1385	    }
1386	}
