1398	    UD.fill2 = NULL;
1399	    UD.trk2 = NULL;
1400	    SET_ARC_OPA(UD.fill, 255);
1401	    SET_ARC_OPA(UD.trk, 255);
1402	    s_mode = s_rot_to_mode;
1403	    s_angle = s_rot_a1;
