1410	/** 环形页旋转：dir = +1 顺时针（→ 键），-1 逆时针（← 键）。
1411	 * 目标角取 to_mode*90 加上足够圈数，保证朝正确方向转；可被下一次按键打断。 */
1412	static void dial_rotate(int dir)
1413	{
1414	    int from_mode;
1415	    int to_mode;
1416	    int a0;
1417	    int target;
1418	    int duration = 160;
1419	    lv_anim_t a;
1420	    if (dir == 0) {
1421	        dir = 1;
1422	    }
1423	
1424	    /* 转场中禁止再转；但盘面旋转本身可以被下一次按键打断（#2）。 */
1425	    if (UD.fill == NULL || (s_busy && s_tr_anim != NULL)) {
1426	        return;
1427	    }
1428	    a0 = (int)s_angle;
1429	
1430	    if (s_rot_anim != NULL) {
1431	        /* ANIMATION #2：从当前角重定目标，120ms；旧 B 升为 A。 */
1432	        lv_anim_delete(&s_rot_p, NULL);
1433	        s_rot_anim = NULL;
1434	        if (UD.fill != NULL) {
1435	            lv_obj_delete(UD.fill);
1436	            lv_obj_delete(UD.trk);
1437	        }
1438	        UD.fill = UD.fill2;
1439	        UD.trk = UD.trk2;
1440	        UD.fill2 = NULL;
1441	        UD.trk2 = NULL;
1442	        from_mode = s_rot_to_mode;
1443	        s_rot_oa0 = s_rot_oa_cur;
1444	        s_rot_ob0 = s_rot_ob_cur;
1445	        s_mode = from_mode;
1446	        duration = 120;
1447	    } else {
1448	        from_mode = s_mode;
1449	        s_rot_oa0 = 255;
1450	        s_rot_ob0 = 0;
1451	    }
1452	    s_rot_oa_cur = s_rot_oa0;
1453	    s_rot_ob_cur = s_rot_ob0;
1454	    to_mode = (from_mode + (dir > 0 ? 1 : -1) + M_COUNT) % M_COUNT;
1455	
1456	    target = to_mode * 90;
1457	    if (dir > 0) {
1458	        while (target <= a0) {
1459	            target += 360;
1460	        }
1461	    } else {
1462	        while (target >= a0) {
1463	            target -= 360;
1464	        }
1465	    }
1466	
1467	    s_rot_a0 = a0;
1468	    s_rot_a1 = target;
1469	    s_rot_from_mode = from_mode;
