564	    memcpy(&s_pts_pool[s_pts_n], src, (size_t)n * sizeof(s_pts_pool[0]));
565	    {
566	        const lv_point_precise_t *p = &s_pts_pool[s_pts_n];
567	
568	        s_pts_n += n;
569	        return p;
570	    }
