    const char *name;  /**< 中文名 */
    const char *sym;   /**< Material Symbols 源名 */
} icon_meta_t;

/* 顺序必须与 helm_icons.h 的 helm_icon_t 一致 */
static const icon_meta_t s_meta[HELM_ICON_COUNT] = {
    { 0xE001, "骑行",   "directions_bike" },
    { 0xE002, "导航",   "navigation"      },
    { 0xE003, "记录",   "bar_chart"       },
