    }
}

/** @brief 30px 模式名（板端没有 30px 点阵档；正常固件走系统 TTF，工厂回退 22px）。 */
static const lv_font_t * helm_ring_name_font(void)
{
    return helm_font_sys(30, s_sh.font_val);
}

static void helm_ring_set_font(lv_obj_t * obj, const lv_font_t * font)
{
    if (obj != NULL && font != NULL &&
        lv_obj_get_style_text_font(obj, 0) != font) {
        lv_obj_set_style_text_font(obj, font, 0);
    }
}

static void helm_ring_set_arc_opa(lv_obj_t * arc, int opa)
{
    if (arc == NULL) {
        return;
    }
    if (opa < 0) {
        opa = 0;
    } else if (opa > 255) {
        opa = 255;
    }
    lv_obj_set_style_arc_opa(arc, (lv_opa_t)opa, LV_PART_INDICATOR);
}

/**
 * @brief 一段扇区弧（只画 indicator；主弧全透明）。
 * @param mode  0..3：角度 = mode*90−90±26（上/右/下/左）。
 * @param width 12 = 浅色填充，2 = 深色外沿。
 */
static lv_obj_t * helm_ring_arc_make(lv_obj_t * parent, int mode, int width,
                                     uint32_t hex, lv_opa_t opa)
{
    lv_obj_t * arc = lv_arc_create(parent);
    int a = (mode & 3) * 90 - 90;

    lv_obj_set_size(arc, HELM_RING_D, HELM_RING_D);
    lv_obj_set_pos(arc, HELM_RING_CX - HELM_RING_D / 2,
                   HELM_RING_CY - HELM_RING_D / 2);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);
    /* 主弧不画，只留 indicator 扇段。 */
    lv_obj_set_style_arc_opa(arc, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 0, LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, false, LV_PART_MAIN);
    lv_obj_set_style_arc_opa(arc, opa, LV_PART_INDICATOR);
    lv_obj_set_style_arc_width(arc, width, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, helm_color(hex), LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, false, LV_PART_INDICATOR);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);
    lv_arc_set_rotation(arc, 0);
    lv_arc_set_range(arc, 0, 100);
    lv_arc_set_value(arc, 100);
    lv_arc_set_bg_angles(arc, (lv_value_precise_t)helm_ring_norm(a - 26),
                         (lv_value_precise_t)helm_ring_norm(a + 26));
    return arc;
}

/** @brief 建一套扇区（浅色填充 + 2px 深色外沿）到指定槽位。 */
static void helm_ring_sector_make(uint8_t slot, int mode)
{
    uint8_t base = ((mode & 3) == 3) ? (uint8_t)LV_OPA_20
                                     : (uint8_t)LV_OPA_COVER;

    s_ring_fill_base[slot] = base;
    s_sh.ring_fill[slot] = helm_ring_arc_make(s_sh.ring, mode, 12,
                                             helm_ring_fill_hex(mode),
                                             (lv_opa_t)base);
    s_sh.ring_trk[slot] = helm_ring_arc_make(s_sh.ring, mode, 2,
                                            helm_ring_ink_hex(mode),
                                            LV_OPA_COVER);
}

/** @brief 24 刻度：整点 3px（INK）、其余 1px（MUTE）。 */
static void helm_ring_build_ticks(lv_obj_t * parent)
{
    int i;

    for (i = 0; i < 24; i++) {
        const int deg = i * 15;
        const bool major = (i % 6) == 0;
        const int th = major ? 3 : 1;
        int x1, y1, x2, y2;
        int x, y, w, h;
        lv_obj_t * box;

        helm_ring_pt(deg, major ? HELM_RING_TICK_RIN_M : HELM_RING_TICK_RIN_m,
                     &x1, &y1);
        helm_ring_pt(deg, HELM_RING_TICK_ROUT, &x2, &y2);
        if (LV_ABS(x2 - x1) >= LV_ABS(y2 - y1)) {
            x = (x1 < x2) ? x1 : x2;
            y = y1;
            w = LV_ABS(x2 - x1) + 1;
            h = th;
        } else {
            x = x1;
            y = (y1 < y2) ? y1 : y2;
            w = th;
            h = LV_ABS(y2 - y1) + 1;
        }

        box = lv_obj_create(parent);
        lv_obj_remove_style_all(box);
        lv_obj_set_pos(box, x, y);
        lv_obj_set_size(box, w, h);
        lv_obj_set_style_bg_color(box,
            helm_color(major ? HELM_COLOR_INK : HELM_COLOR_MUTE), 0);
        lv_obj_set_style_bg_opa(box, LV_OPA_COVER, 0);
        lv_obj_set_style_radius(box, th / 2, 0);
        lv_obj_remove_flag(box, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(box, LV_OBJ_FLAG_SCROLLABLE);
        s_sh.ring_tick[i] = box;
    }
}

/** @brief 指针：中心 → r=72 的杆 + 末端 8px 横杆。 */
static void helm_ring_pointer_layout(int32_t angle)
{
    const int a = helm_ring_norm((int)angle);
    const int32_t sn = lv_trigo_sin((int16_t)a);
    const int32_t cs = lv_trigo_cos((int16_t)a);
    const int sx = (int)sn;
    const int sy = (int)(-cs);
    const int px = (int)cs;
    const int py = (int)sn;
    const int x0 = HELM_RING_CX + helm_ring_trig(sx, HELM_RING_PTR_R0);
    const int y0 = HELM_RING_CY + helm_ring_trig(sy, HELM_RING_PTR_R0);
    const int x1 = HELM_RING_CX + helm_ring_trig(sx, HELM_RING_PTR_R1);
    const int y1 = HELM_RING_CY + helm_ring_trig(sy, HELM_RING_PTR_R1);

    s_sh.ring_ptr_pts[0].x = x0;
    s_sh.ring_ptr_pts[0].y = y0;
    s_sh.ring_ptr_pts[1].x = x1;
    s_sh.ring_ptr_pts[1].y = y1;
    s_sh.ring_cross_pts[0].x =
        x1 - helm_ring_trig(px, HELM_RING_PTR_CROSS);
    s_sh.ring_cross_pts[0].y =
        y1 - helm_ring_trig(py, HELM_RING_PTR_CROSS);
    s_sh.ring_cross_pts[1].x =
        x1 + helm_ring_trig(px, HELM_RING_PTR_CROSS);
    s_sh.ring_cross_pts[1].y =
        y1 + helm_ring_trig(py, HELM_RING_PTR_CROSS);
    if (s_sh.ring_ptr != NULL) {
        lv_line_set_points(s_sh.ring_ptr, s_sh.ring_ptr_pts, 2);
    }
    if (s_sh.ring_cross != NULL) {
        lv_line_set_points(s_sh.ring_cross, s_sh.ring_cross_pts, 2);
    }
}

/** @brief 标题行：名字 160 宽居中；20px 图标贴在文字墨迹左侧（同模拟器）。 */
static void helm_ring_title_layout(void)
{
    const lv_font_t * nf = helm_ring_name_font();
    lv_point_t sz;
    int left;

    if (s_sh.ring_name == NULL) {
        return;
    }
    lv_text_get_size(&sz, lv_label_get_text(s_sh.ring_name), nf, 0, 0,
                     LV_COORD_MAX, LV_TEXT_FLAG_NONE);
    left = HELM_RING_HUB_W / 2 - (int)sz.x / 2;
    lv_obj_set_pos(s_sh.ring_name, 0, 0);
    if (s_sh.ring_icon != NULL) {
        lv_obj_set_pos(s_sh.ring_icon, left - 2 - 20, 19 - 10);
    }
}

/** @brief 主值按 hub 中线居中；单位挂在右侧、与主值共用基线。 */
static void helm_ring_value_layout(const char * txt, bool has_unit,
                                   const char * unit)
{
    const lv_font_t * vf = s_sh.font_val;
    const lv_font_t * uf = s_sh.font_lab;
    lv_point_t sz;
    int vx;

    if (s_sh.ring_value == NULL) {
        return;
    }
    lv_text_get_size(&sz, txt, vf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
    vx = HELM_RING_HUB_W / 2 - (int)sz.x / 2;
    lv_obj_set_pos(s_sh.ring_value, vx, 55);

    if (s_sh.ring_unit == NULL) {
        return;
    }
    if (!has_unit) {
        helm_show(s_sh.ring_unit, false);
        return;
    }

    {
        const int vb = lv_font_get_line_height(vf) - vf->base_line;
        const int ub = lv_font_get_line_height(uf) - uf->base_line;

        lv_obj_set_pos(s_sh.ring_unit, vx + (int)sz.x + 3, 55 + vb - ub);
    }
    helm_label_set(s_sh.ring_unit, unit);
    helm_show(s_sh.ring_unit, true);
}

/** @brief 四个模式名：选中 = 模式色 + 15px，其余 = mute + 12px。 */
static void helm_ring_paint_labels(int mode)
{
    int i;

    for (i = 0; i < 4; i++) {
        const bool sel = (i == (mode & 3));

        helm_ring_set_font(s_sh.ring_lab[i],
                           sel ? s_sh.font_title : s_sh.font_lab);
        helm_set_text_hex(s_sh.ring_lab[i],
                          sel ? helm_ring_ink_hex(mode) : HELM_COLOR_MUTE);
    }
}

/** @brief 换模式：名字/描述/图标/四方位标签（不动数值那一组）。 */
static void helm_ring_paint_mode(int mode)
{
    mode &= 3;
    s_sh.ring_mode = (uint8_t)mode;
    if (s_sh.ring_name == NULL) {
        return;
    }

    helm_ring_set_font(s_sh.ring_name, helm_ring_name_font());
    helm_label_set(s_sh.ring_name, s_ring_names[mode]);
    helm_set_text_hex(s_sh.ring_name, HELM_COLOR_INK);
    helm_ring_title_layout();

    if (s_sh.ring_icon != NULL) {
        hfi_set(s_sh.ring_icon, helm_ring_icon_id(mode));
        lv_obj_set_style_text_color(s_sh.ring_icon,
                                    helm_color(helm_ring_ink_hex(mode)), 0);
    }
    helm_label_set(s_sh.ring_desc, s_ring_descs[mode]);
    helm_set_text_hex(s_sh.ring_desc, HELM_COLOR_MUTE);
    helm_ring_paint_labels(mode);
}

/**
 * @brief 盘下统计行。
 * @details **缺口**：GPX 列表/周聚合在 `helm_menu.c` 里是私有表（本包只被允许
 *          新增 `helm_menu_open_at()`），helm_shell 拿不到"本周里程 / 次数 /
 *          最近日期" ⇒ 按任务允许的降级：显示"上次骑行 X km · 记录数未知"，
 *          7 根迷你柱保持隐藏（不自造内存周数据）。见 S2/NOTES.md。
 */
static void helm_ring_week_sync(void)
{
    char buf[64];

    if (s_sh.ring_week == NULL) {
        return;
    }
    if (s_sh.last_km > 0.05f) {
        char km[16];

        helm_fmt_km(km, sizeof(km), s_sh.last_km);
        lv_snprintf(buf, sizeof(buf), "上次骑行 %s km · 记录数未知", km);
    } else {
        lv_snprintf(buf, sizeof(buf), "暂无骑行记录");
    }
    helm_label_set(s_sh.ring_week, buf);
    helm_set_text_hex(s_sh.ring_week, HELM_COLOR_INK);
}

/** @brief 盘心数值 + 副行（每 500ms 刷新；只改文本与水平居中）。 */
static void helm_ring_paint_values(const bicycle_runtime_t * rt)
{
    char v[24];
    char u[8];
    char sub[64];
    char km[16];
    bool has_unit = false;
    const int mode = s_sh.ring_mode & 3;

    v[0] = '\0';
    u[0] = '\0';
    sub[0] = '\0';

    switch (mode) {
    case 0:
        /* 骑行：上次骑行里程（来源 = shell 既有的 last_km，即
         * myvendor_devctl_last_ride_m_get / 保存骑行时回写）。 */
        if (s_sh.last_km > 0.05f) {
            helm_fmt_km(km, sizeof(km), s_sh.last_km);
        } else {
            lv_snprintf(km, sizeof(km), "0.0");
        }
        lv_snprintf(v, sizeof(v), "%s", km);
        lv_snprintf(u, sizeof(u), "km");
        has_unit = true;
        if (helm_riding()) {
            char sp[16];

            helm_fmt_speed(sp, sizeof(sp), helm_session_avg_kph(rt));
            lv_snprintf(sub, sizeof(sub), "均速 %s km/h", sp);
        } else {
            lv_snprintf(sub, sizeof(sub), "上次骑行");
        }
        break;

    case 1:
        if (s_sh.map != NULL && map_page_nav_active(s_sh.map)) {
            double rem = map_page_nav_remain_m(s_sh.map);
            double tot = map_page_nav_total_m(s_sh.map);
            char tk[16];

            if (rem < 0.0) {
                rem = 0.0;
            }
            if (tot < 0.0) {
                tot = 0.0;
            }
            helm_fmt_km(km, sizeof(km), (float)(rem / 1000.0));
            helm_fmt_km(tk, sizeof(tk), (float)(tot / 1000.0));
            lv_snprintf(v, sizeof(v), "%s", km);
            lv_snprintf(u, sizeof(u), "km");
            has_unit = true;
            lv_snprintf(sub, sizeof(sub), "全程 %s km", tk);
        } else {
            lv_snprintf(v, sizeof(v), "--");
            lv_snprintf(sub, sizeof(sub), "未在导航");
        }
        break;

    case 2:
        /* 记录：拿不到 GPX 条数/最近日期 ⇒ 显示上次记录里程，副行"暂无"。 */
        if (s_sh.last_km > 0.05f) {
            helm_fmt_km(km, sizeof(km), s_sh.last_km);
        } else {
            lv_snprintf(km, sizeof(km), "0.0");
        }
        lv_snprintf(v, sizeof(v), "%s", km);
        lv_snprintf(u, sizeof(u), "km");
        has_unit = true;
        lv_snprintf(sub, sizeof(sub), "暂无记录日期");
        break;

    default: {
        int pct = myvendor_sys_battery_percent();
        const char * ver = myvendor_sw_version();

        if (pct < 0) {
            pct = 0;
        } else if (pct > 100) {
            pct = 100;
        }
        lv_snprintf(v, sizeof(v), "%d", pct);
        lv_snprintf(u, sizeof(u), "%%");
        has_unit = true;
        lv_snprintf(sub, sizeof(sub), "%s",
                    (ver != NULL && ver[0] != '\0') ? ver : "--");
        break;
    }
    }

    helm_label_set(s_sh.ring_value, v);
    helm_set_text_hex(s_sh.ring_value, HELM_COLOR_INK);
    helm_ring_value_layout(v, has_unit, u);
    helm_label_set(s_sh.ring_sub, sub);
    helm_set_text_hex(s_sh.ring_sub, HELM_COLOR_MUTE);
    helm_ring_week_sync();
}

static void helm_ring_paint_all(void)
{
    helm_ring_paint_mode(s_sh.ring_mode & 3);
    helm_ring_paint_values(bicycle_runtime_get());
}

/** @brief 500ms 节拍：旋转中不刷（交叉淡入与数值换行抢同一帧会抖）。 */
static void helm_ring_tick(const bicycle_runtime_t * rt)
{
    if (s_sh.ring == NULL || s_sh.ring_busy) {
        return;
    }
    helm_ring_paint_values(rt);
}

static void helm_ring_anim_exec(void * var, int32_t p)
{
    int fa, fb, ta, tb;

    LV_UNUSED(var);
    if (!s_sh.ring_busy || helm_anim_is_suspended()) {
        return;
    }

    s_sh.ring_angle = s_ring_ang0 + (s_ring_ang1 - s_ring_ang0) * p / 1000;
    helm_ring_pointer_layout(s_sh.ring_angle);

    fa = (int)s_ring_fa0 * (1000 - (int)p) / 1000;
    fb = (int)s_ring_fb1 * (int)p / 1000;
    ta = 255 * (1000 - (int)p) / 1000;
    tb = 255 * (int)p / 1000;
    helm_ring_set_arc_opa(s_sh.ring_fill[s_ring_slot], fa);
    helm_ring_set_arc_opa(s_sh.ring_trk[s_ring_slot], ta);
    helm_ring_set_arc_opa(s_sh.ring_fill[s_ring_slot ^ 1u], fb);
    helm_ring_set_arc_opa(s_sh.ring_trk[s_ring_slot ^ 1u], tb);

    if (!s_ring_swapped && p >= 500) {
        s_ring_swapped = true;
        helm_ring_paint_mode(s_ring_to_mode);
        helm_ring_paint_values(bicycle_runtime_get());
    }
}

/** @brief 把旋转收尾到目标态（动画完成 / 被覆盖取消共用）。 */
static void helm_ring_anim_finish(void)
{
    const uint8_t slot = s_ring_slot;
    const uint8_t nslot = (uint8_t)(slot ^ 1u);

    if (s_sh.ring_fill[slot] != NULL) {
        lv_obj_delete(s_sh.ring_fill[slot]);
        s_sh.ring_fill[slot] = NULL;
    }
    if (s_sh.ring_trk[slot] != NULL) {
        lv_obj_delete(s_sh.ring_trk[slot]);
        s_sh.ring_trk[slot] = NULL;
    }
    s_ring_slot = nslot;
    helm_ring_set_arc_opa(s_sh.ring_fill[nslot], s_ring_fill_base[nslot]);
    helm_ring_set_arc_opa(s_sh.ring_trk[nslot], 255);
    s_sh.ring_angle = s_ring_ang1;
    s_sh.ring_busy = false;
    helm_ring_pointer_layout(s_sh.ring_angle);
    helm_ring_paint_mode(s_ring_to_mode);
    helm_ring_paint_values(bicycle_runtime_get());
    printf("helm: ring rotate done mode=%d angle=%d\n",
           (int)s_sh.ring_mode, (int)helm_ring_norm((int)s_sh.ring_angle));
}

static void helm_ring_anim_done(lv_anim_t * a)
{
    LV_UNUSED(a);
    if (s_sh.ring_busy) {
        helm_ring_anim_finish();
    }
}

static void helm_ring_anim_cancel(void)
{
    if (!s_sh.ring_busy) {
        return;
    }
    lv_anim_delete(&s_ring_anim_v, helm_ring_anim_exec);
    helm_ring_anim_finish();
}

/**
 * @brief 环转一格。
 * @param dir +1 顺时针（KEY2 短）、−1 逆时针（KEY1 短）。
 * @details 160ms；只失效 pointer 折线、两套 140×140 扇区弧和盘心两块文字。
 *          旋转中再次按键**丢弃**（板上 100~200ms/帧，叠加动画只会更卡）。
 */
static void helm_ring_rotate(int dir)
{
    int from;
    int to;
    int32_t a0;
    int32_t target;
    uint8_t slot;
    uint8_t nslot;
    lv_anim_t a;

    if (!s_sh.attached || s_sh.ring == NULL ||
        s_sh.view_id != HELM_PAGE_RING) {
        return;
    }
    if (s_sh.ring_busy) {
        printf("helm: ring rotate busy, drop\n");
        return;
    }
    if (dir == 0) {
        dir = 1;
    }

    from = s_sh.ring_mode & 3;
    to = (from + ((dir > 0) ? 1 : 3)) & 3;
    a0 = s_sh.ring_angle;
    target = (int32_t)to * 90;
    if (dir > 0) {
        while (target <= a0) {
            target += 360;
        }
    } else {
        while (target >= a0) {
            target -= 360;
        }
    }

    slot = s_ring_slot;
    nslot = (uint8_t)(slot ^ 1u);
    if (s_sh.ring_fill[nslot] != NULL) {
        lv_obj_delete(s_sh.ring_fill[nslot]);
        s_sh.ring_fill[nslot] = NULL;
    }
    if (s_sh.ring_trk[nslot] != NULL) {
        lv_obj_delete(s_sh.ring_trk[nslot]);
        s_sh.ring_trk[nslot] = NULL;
    }
    helm_ring_sector_make(nslot, to);
    /* 新扇区从 0 起步：建完立刻按 0 拨下去（sector_make 给了最终值）。 */
    helm_ring_set_arc_opa(s_sh.ring_fill[nslot], 0);
    helm_ring_set_arc_opa(s_sh.ring_trk[nslot], 0);

    s_ring_fa0 = s_ring_fill_base[slot];
    s_ring_fb1 = s_ring_fill_base[nslot];
    s_ring_ang0 = a0;
    s_ring_ang1 = target;
    s_ring_from_mode = from;
    s_ring_to_mode = to;
    s_ring_swapped = false;
    s_sh.ring_busy = true;

    printf("helm: ring rotate %s mode=%d->%d angle=%d->%d\n",
           (dir > 0) ? "cw" : "ccw", from, to, (int)a0, (int)target);

    lv_anim_init(&a);
    lv_anim_set_var(&a, &s_ring_anim_v);
    lv_anim_set_values(&a, 0, 1000);
    lv_anim_set_duration(&a, HELM_RING_ANIM_MS);
    lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
    lv_anim_set_exec_cb(&a, helm_ring_anim_exec);
    lv_anim_set_completed_cb(&a, helm_ring_anim_done);
    lv_anim_start(&a);
}

/**
 * @brief 进入当前模式。
 * @details 骑行 → 先开始/继续记录，再落到骑行页（DATA）；
 *          导航/记录/设置 → 菜单根行（0 / 4 / 6，0 基）。
 */
static void helm_ring_enter(int mode)
{
    switch (mode & 3) {
    case 0:
        helm_shell_ensure_ride();
        if (helm_riding()) {
            if (!helm_nav_on()) {
                s_sh.ride_idx = 0;
            }
            helm_apply_view();
            helm_refresh_numbers();
        }
        break;
    case 1:
        if (helm_menu_open_at(0) != 0) {
            printf("helm: ring menu(nav) open failed\n");
        }
        break;
    case 2:
