 *          GPX 列表里。行号越界时退回第一行（paint 自己也会再夹一次）。
 */
static void helm_root_jump_apply(helm_menu_t * m)
{
    const int prefix = helm_root_prefix_rows();
    const int total = prefix + (int)(sizeof(P_ROOT) / sizeof(P_ROOT[0]));
    int row;

    if (s_root_jump < 0 || m == NULL) {
        return;
    }

    row = s_root_jump + prefix;
    if (row < 0 || row >= total || row >= HELM_MENU_ROWS) {
        row = 0;
    }
    m->sp = 1;
    m->stack[0].scr = HELM_SCR_ROOT;
    m->stack[0].sel = (uint8_t)row;
    s_root_jump = -1;
    s_list_enter_dir = 1;
}
